def blocks(grid):
    from collections import Counter
    c=Counter(v for row in grid for v in row if v)
    res={}
    for col in c:
        cells=[(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if v==col]
        rs=[x[0] for x in cells]; cs=[x[1] for x in cells]
        area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
        res[col]=(len(cells), area, len(cells)/area)
    return res
